/*
 * High Priestess Arlokk with Ascension's spells.
 *
 * Kit: Ascension's block 2118300-2118340. Timings: a Bronzebeard kill on video,
 * see raid-difficulty-werkzeug/zg-video-zeitplan.json. Claw Storm's repeat and
 * Fierce Blow follow the CoA combat log of 2026-08-02.
 *
 * From stock: the prowlers streaming in from both sides, her vanish after 30
 * seconds, the panther phase and the return to troll form, the gong and the
 * despawn when the raid wipes.
 *
 *   Troll form
 *     Shadow Word: Pain  first 2s,  every 20s   the tank
 *     Mark of Arlokk     at 10s                 a player the prowlers hunt;
 *                                               when the mark is gone, it
 *                                               jumps to another player
 *     Kidney Shot        first 15s, every 30s   the tank, 4s stun
 *
 *   Panther form (her Aspect of Bethekk)
 *     Claw Storm         first 5s,  every 55s   spins for 8s, 5 yards around her
 *     Ravage             first 10s, every 15s   the tank, pinned and mauled
 *     Shadowstep         first 12s, every 15s   behind a random player
 *     Razor Claws        passive, her hits bleed
 *
 *   Both forms
 *     Fierce Blow        first 6.7-17.3s, every 6-10s   on the tank
 *
 *   At 50% she drains the Avatar of Bethekk (see LoaAvatar), taking ~1% damage
 *   while it dies, then gains the Gift of the Blood God. Her panther form keeps
 *   its own timer: in the CoA log her Razor Claws came almost a minute before
 *   the drain.
 *
 * Decided here, not in the data:
 *   - Claw Storm's first cast, Ravage and Shadowstep timers (each appears once or twice in
 *     the video); Kidney Shot's first cast;
 *   - the mark lasts until it is removed and does not stack; prowlers within
 *     40 yards of the marked player turn on them every 2 seconds.
 */

#include "CreatureScript.h"
#include "GameObject.h"
#include "InstanceScript.h"
#include "ScriptedCreature.h"
#include "../../../src/server/scripts/EasternKingdoms/ZulGurub/zulgurub.h"
#include "zg_coa_common.h"

#include <list>

using namespace coa_zg;

namespace
{
    enum Says
    {
        SAY_AGGRO         = 0,
        SAY_FEAST_PROWLER = 1,
        SAY_DEATH         = 2
    };

    enum Spells
    {
        SPELL_SUMMON_PROWLER     = 24246,
        SPELL_VANISH_VISUAL      = 24222,
        SPELL_VANISH             = 24223,
        SPELL_SUPER_INVIS        = 24235,

        INFO_SHADOW_WORD_PAIN    = 2118301,
        SPELL_SHADOW_WORD_PAIN   = 2118305,
        SPELL_SHADOW_WORD_PAIN_DOT = 2118306,
        SPELL_KIDNEY_SHOT        = 2118307,
        SPELL_SHADOWSTEP         = 2118308,
        SPELL_MARK_OF_ARLOKK     = 2118310,
        SPELL_MARK_OF_ARLOKK_AURA = 2118311,
        SPELL_DRAIN_POWER        = 2118322,
        SPELL_ASPECT_OF_BETHEKK  = 2118323,
        SPELL_GIFT_OF_THE_BLOOD_GOD = 2118324,
        SPELL_RAZOR_CLAWS        = 2118325,
        SPELL_RAVAGE             = 2118330,
        SPELL_CLAW_STORM         = 2118336,
    };

    enum Events
    {
        EVENT_SHADOW_WORD_PAIN = 1,
        EVENT_KIDNEY_SHOT,
        EVENT_MARK_OF_ARLOKK,
        EVENT_MARK_CHECK,
        EVENT_SUMMON_PROWLERS,
        EVENT_TRANSFORM,
        EVENT_VANISH,
        EVENT_VANISH_2,
        EVENT_VISIBLE,
        EVENT_CLAW_STORM,
        EVENT_RAVAGE,
        EVENT_SHADOWSTEP,
        EVENT_TRANSFORM_BACK,
        EVENT_FIERCE_BLOW,
    };

    enum Phases
    {
        PHASE_ALL   = 0,
        PHASE_ONE   = 1,
        PHASE_TWO   = 2
    };

    constexpr uint32 NPC_AVATAR_OF_BETHEKK = 666988;
    constexpr uint32 WEAPON_DAGGER       = 10616;
    constexpr uint8 MAX_PROWLERS_PER_SIDE = 15;
    constexpr float MARK_PULL_RANGE      = 40.0f;

    Position const PosMoveOnSpawn = { -11561.9f, -1627.868f, 41.29941f, 0.0f };

    struct boss_arlokk_coa : public BossAI
    {
        boss_arlokk_coa(Creature* creature) : BossAI(creature, DATA_ARLOKK) { }

        void Reset() override
        {
            _Reset();
            _summonCountA = 0;
            _summonCountB = 0;
            _marking = false;
            _drained = false;
            _avatar.Despawn(me);
            me->RemoveAurasDueToSpell(SPELL_GIFT_OF_THE_BLOOD_GOD);
            me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_BETHEKK);
            me->RemoveAurasDueToSpell(SPELL_RAZOR_CLAWS);
            me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 0, WEAPON_DAGGER);
            me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 1, WEAPON_DAGGER);
            me->SetWalk(false);
            me->SetHomePosition(PosMoveOnSpawn);
            me->GetMotionMaster()->MoveTargetedHome();
        }

        void JustDied(Unit* /*killer*/) override
        {
            _JustDied();
            _avatar.Despawn(me);
            Talk(SAY_DEATH);
            ClearMarks();
        }

        void JustEngagedWith(Unit* /*who*/) override
        {
            _JustEngagedWith();
            Talk(SAY_AGGRO);
            _avatar.Summon(me);

            events.SetPhase(PHASE_ONE);
            ScheduleTroll(2s);
            events.ScheduleEvent(EVENT_SUMMON_PROWLERS, 6s, 0, PHASE_ALL);
            events.ScheduleEvent(EVENT_MARK_OF_ARLOKK, 10s, 0, PHASE_ALL);
            events.ScheduleEvent(EVENT_FIERCE_BLOW, FIERCE_BLOW_FIRST_MIN, FIERCE_BLOW_FIRST_MAX, 0, PHASE_ALL);

            // The panther spawners, split by side as in stock.
            std::list<Creature*> triggers;
            GetCreatureListWithEntryInGrid(triggers, me, NPC_PANTHER_TRIGGER, 100.0f);
            uint8 sideA = 0, sideB = 0;
            for (Creature* trigger : triggers)
            {
                if (trigger->GetPositionY() < -1625.0f)
                {
                    if (sideA < 5)
                        _sideA[sideA++] = trigger->GetGUID();
                }
                else if (sideB < 5)
                    _sideB[sideB++] = trigger->GetGUID();
            }
        }

        void ScheduleTroll(Milliseconds swp)
        {
            events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, swp, 0, PHASE_ONE);
            events.ScheduleEvent(EVENT_KIDNEY_SHOT, 15s, 0, PHASE_ONE);
            events.ScheduleEvent(EVENT_TRANSFORM, 30s, 0, PHASE_ONE);
        }

        void JustReachedHome() override
        {
            if (GameObject* gong = ObjectAccessor::GetGameObject(*me, instance->GetGuidData(GO_GONG_OF_BETHEKK)))
                gong->RemoveGameObjectFlag(GO_FLAG_NOT_SELECTABLE);
            me->DespawnOrUnsummon();
        }

        void EnterEvadeMode(EvadeReason why) override
        {
            BossAI::EnterEvadeMode(why);
            _avatar.Despawn(me);
            ClearMarks();
            std::list<Creature*> panthers;
            GetCreatureListWithEntryInGrid(panthers, me, NPC_ZULIAN_PROWLER, 200.0f);
            for (Creature* panther : panthers)
                panther->DespawnOrUnsummon();
        }

        void DamageTaken(Unit* attacker, uint32& damage, DamageEffectType type, SpellSchoolMask school) override
        {
            BossAI::DamageTaken(attacker, damage, type, school);

            if (_drained || !me->HealthBelowPctDamaged(50, damage))
                return;

            _drained = true;
            if (!_avatar.Drain(me))
                DoCastSelf(SPELL_GIFT_OF_THE_BLOOD_GOD, true);
        }

        // A prowler died on side 1 or 2.
        void SetData(uint32 id, uint32 /*value*/) override
        {
            if (id == 1 && _summonCountA)
                --_summonCountA;
            else if (id == 2 && _summonCountB)
                --_summonCountB;
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            Unit* target = ObjectAccessor::GetUnit(*me, _target);
            if (spell->Id == SPELL_SHADOW_WORD_PAIN)
                Hit(me, target, SPELL_SHADOW_WORD_PAIN_DOT, Info(me, INFO_SHADOW_WORD_PAIN));
            else if (spell->Id == SPELL_MARK_OF_ARLOKK && target)
            {
                me->AddAura(SPELL_MARK_OF_ARLOKK_AURA, target);
                Talk(SAY_FEAST_PROWLER, target);
            }
        }

        Player* Marked()
        {
            for (Player* p : Players(me, [](Player* x) { return x->HasAura(SPELL_MARK_OF_ARLOKK_AURA); }))
                return p;
            return nullptr;
        }

        void ClearMarks()
        {
            me->GetMap()->DoForAllPlayers([](Player* p) { p->RemoveAurasDueToSpell(SPELL_MARK_OF_ARLOKK_AURA); });
        }

        void Mark()
        {
            if (Unit* target = SelectTarget(SelectTargetMethod::Random, 1, 100.0f, true))
            {
                _target = target->GetGUID();
                DoCast(target, SPELL_MARK_OF_ARLOKK, true);
            }
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            if (_avatar.Consumed(me))
                DoCastSelf(SPELL_GIFT_OF_THE_BLOOD_GOD, true);

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_SHADOW_WORD_PAIN:
                        if (Unit* tank = me->GetVictim())
                        {
                            _target = tank->GetGUID();
                            DoCast(tank, SPELL_SHADOW_WORD_PAIN);
                        }
                        events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, 20s, 0, PHASE_ONE);
                        break;
                    case EVENT_KIDNEY_SHOT:
                        DoCastVictim(SPELL_KIDNEY_SHOT);
                        events.ScheduleEvent(EVENT_KIDNEY_SHOT, 30s, 0, PHASE_ONE);
                        break;
                    case EVENT_MARK_OF_ARLOKK:
                        _marking = true;
                        Mark();
                        events.ScheduleEvent(EVENT_MARK_CHECK, 2s, 0, PHASE_ALL);
                        break;
                    case EVENT_MARK_CHECK:
                        if (Player* marked = Marked())
                        {
                            std::list<Creature*> prowlers;
                            GetCreatureListWithEntryInGrid(prowlers, marked, NPC_ZULIAN_PROWLER, MARK_PULL_RANGE);
                            for (Creature* prowler : prowlers)
                                if (prowler->IsAlive() && prowler->GetVictim() != marked)
                                {
                                    prowler->GetThreatMgr().AddThreat(marked, 100000.0f);
                                    prowler->AI()->AttackStart(marked);
                                }
                        }
                        else if (_marking)
                            Mark();   // the mark jumps
                        events.ScheduleEvent(EVENT_MARK_CHECK, 2s, 0, PHASE_ALL);
                        break;
                    case EVENT_SUMMON_PROWLERS:
                        if (_summonCountA < MAX_PROWLERS_PER_SIDE)
                            if (Unit* trigger = ObjectAccessor::GetUnit(*me, _sideA[urand(0, 4)]))
                            {
                                trigger->CastSpell(trigger, SPELL_SUMMON_PROWLER);
                                ++_summonCountA;
                            }
                        if (_summonCountB < MAX_PROWLERS_PER_SIDE)
                            if (Unit* trigger = ObjectAccessor::GetUnit(*me, _sideB[urand(0, 4)]))
                            {
                                trigger->CastSpell(trigger, SPELL_SUMMON_PROWLER);
                                ++_summonCountB;
                            }
                        events.ScheduleEvent(EVENT_SUMMON_PROWLERS, 6s, 0, PHASE_ALL);
                        break;
                    case EVENT_TRANSFORM:
                        DoCastSelf(SPELL_ASPECT_OF_BETHEKK, true);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 0, EQUIP_UNEQUIP);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 1, EQUIP_UNEQUIP);
                        me->AttackStop();
                        DoResetThreatList();
                        me->SetReactState(REACT_PASSIVE);
                        me->SetUnitFlag(UNIT_FLAG_NON_ATTACKABLE | UNIT_FLAG_NOT_SELECTABLE);
                        DoCastSelf(SPELL_VANISH_VISUAL);
                        DoCastSelf(SPELL_VANISH);
                        events.ScheduleEvent(EVENT_VANISH, 1s, 0, PHASE_ONE);
                        break;
                    case EVENT_VANISH:
                        DoCastSelf(SPELL_SUPER_INVIS);
                        me->SetWalk(false);
                        me->GetMotionMaster()->MovePoint(0, frand(-11551.0f, -11508.0f), frand(-1638.0f, -1617.0f), me->GetPositionZ());
                        events.ScheduleEvent(EVENT_VANISH_2, 9s, 0, PHASE_ONE);
                        break;
                    case EVENT_VANISH_2:
                        DoCastSelf(SPELL_VANISH);
                        DoCastSelf(SPELL_SUPER_INVIS);
                        events.ScheduleEvent(EVENT_VISIBLE, 41s, 47s, 0, PHASE_ONE);
                        break;
                    case EVENT_VISIBLE:
                        me->SetReactState(REACT_AGGRESSIVE);
                        me->RemoveUnitFlag(UNIT_FLAG_NON_ATTACKABLE | UNIT_FLAG_NOT_SELECTABLE);
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0))
                            AttackStart(target);
                        me->RemoveAurasDueToSpell(SPELL_SUPER_INVIS);
                        me->RemoveAurasDueToSpell(SPELL_VANISH);
                        DoCastSelf(SPELL_RAZOR_CLAWS, true);
                        events.SetPhase(PHASE_TWO);
                        events.ScheduleEvent(EVENT_CLAW_STORM, 5s, 0, PHASE_TWO);
                        events.ScheduleEvent(EVENT_RAVAGE, 10s, 0, PHASE_TWO);
                        events.ScheduleEvent(EVENT_SHADOWSTEP, 12s, 0, PHASE_TWO);
                        events.ScheduleEvent(EVENT_TRANSFORM_BACK, 30s, 40s, 0, PHASE_TWO);
                        break;
                    case EVENT_CLAW_STORM:
                        DoCastSelf(SPELL_CLAW_STORM);
                        events.ScheduleEvent(EVENT_CLAW_STORM, 55s, 0, PHASE_TWO);
                        break;
                    case EVENT_RAVAGE:
                        DoCastVictim(SPELL_RAVAGE, true);
                        events.ScheduleEvent(EVENT_RAVAGE, 15s, 0, PHASE_TWO);
                        break;
                    case EVENT_SHADOWSTEP:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 40.0f, true))
                        {
                            DoCast(target, SPELL_SHADOWSTEP);
                            AttackStart(target);
                        }
                        events.ScheduleEvent(EVENT_SHADOWSTEP, 15s, 0, PHASE_TWO);
                        break;
                    case EVENT_TRANSFORM_BACK:
                        me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_BETHEKK);
                        me->RemoveAurasDueToSpell(SPELL_RAZOR_CLAWS);
                        DoCastSelf(SPELL_VANISH_VISUAL);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 0, WEAPON_DAGGER);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 1, WEAPON_DAGGER);
                        events.SetPhase(PHASE_ONE);
                        ScheduleTroll(4s);
                        break;
                    case EVENT_FIERCE_BLOW:
                        DoCastVictim(SPELL_FIERCE_BLOW);
                        events.Repeat(FIERCE_BLOW_MIN, FIERCE_BLOW_MAX);
                        break;
                    default:
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        uint8 _summonCountA = 0;
        uint8 _summonCountB = 0;
        bool _marking = false;
        bool _drained = false;
        LoaAvatar _avatar{ NPC_AVATAR_OF_BETHEKK, SPELL_DRAIN_POWER };
        ObjectGuid _sideA[5];
        ObjectGuid _sideB[5];
        ObjectGuid _target;
    };
}

void AddCoaArlokkScripts()
{
    RegisterZulGurubCreatureAI(boss_arlokk_coa);
}

/*
 * Gri'lek (Edge of Madness) with Ascension's spells.
 *
 * Kit: Ascension's block 2118800-2118810. No cast bars in the video; the
 * timings are the Bronzebeard player's DBM bars and boss emotes:
 * "Gri'lek sets his sights on <player>!" with a 20s Fixate bar, and "Next
 * Ground Tremor" every 11-15s. Ground Slam's timer follows the CoA combat log of
 * 2026-08-02.
 *
 *   Relentless Pursuit  from the pull, a new player every 20s (at once when
 *                       the hunted one dies): he ignores everyone else
 *   Avatar              the whole fight: +100% damage, -50% speed, he is
 *                       meant to be kited
 *   Ground Slam         first 24s, every 25s   everyone: Physical damage and
 *                                              an 8s bleed (Trauma); those within
 *                                              20 yards are stunned 2s (Ground
 *                                              Tremor)
 *
 * Decided here, not in the data:
 *   - Avatar for the whole fight (the kit has it, the video cannot show when);
 *   - Ground Slam and Ground Tremor fire together: DBM calls the bar "Ground
 *     Tremor", the kit's damage is the slam;
 *   - the video sometimes shows two fixates at once; here there is one.
 * Hazza'rah, Renataki and Wushoolay keep stock: Ascension has no spells for them.
 */

#include "CreatureScript.h"
#include "ScriptedCreature.h"
#include "../../../src/server/scripts/EasternKingdoms/ZulGurub/zulgurub.h"
#include "zg_coa_common.h"

using namespace coa_zg;

namespace
{
    enum Spells
    {
        SPELL_AVATAR             = 83068,
        SPELL_GROUND_TREMOR      = 6524,
        SPELL_PURSUIT            = 2118801,
        SPELL_TRAUMA             = 2118802,
        SPELL_GROUND_SLAM        = 2118806,
        SPELL_GROUND_SLAM_HIT    = 2118807,
    };

    enum Events
    {
        EVENT_PURSUIT = 1,
        EVENT_GROUND_SLAM,
    };

    constexpr float PURSUIT_THREAT = 1000000.0f;

    struct boss_grilek_coa : public BossAI
    {
        boss_grilek_coa(Creature* creature) : BossAI(creature, DATA_EDGE_OF_MADNESS) { }

        void Reset() override
        {
            StopPursuit();
            BossAI::Reset();
        }

        void JustEngagedWith(Unit* who) override
        {
            BossAI::JustEngagedWith(who);
            DoCastSelf(SPELL_AVATAR, true);
            events.ScheduleEvent(EVENT_PURSUIT, 1s);
            events.ScheduleEvent(EVENT_GROUND_SLAM, 24s);
        }

        void JustDied(Unit* killer) override
        {
            StopPursuit();
            BossAI::JustDied(killer);
        }

        void KilledUnit(Unit* victim) override
        {
            if (victim->GetGUID() == _hunted)
            {
                events.CancelEvent(EVENT_PURSUIT);
                events.ScheduleEvent(EVENT_PURSUIT, 1s);
            }
        }

        void StopPursuit()
        {
            if (Unit* hunted = ObjectAccessor::GetUnit(*me, _hunted))
            {
                hunted->RemoveAurasDueToSpell(SPELL_PURSUIT);
                if (me->GetThreatMgr().GetThreat(hunted) >= PURSUIT_THREAT)
                    me->GetThreatMgr().AddThreat(hunted, -PURSUIT_THREAT);
            }
            _hunted.Clear();
        }

        void Pursue()
        {
            Unit* previous = ObjectAccessor::GetUnit(*me, _hunted);
            StopPursuit();
            Unit* target = SelectTarget(SelectTargetMethod::Random, 0, [previous](Unit* u) { return u->IsPlayer() && u != previous; });
            if (!target)
                target = previous;
            if (!target || !target->IsAlive())
                return;

            _hunted = target->GetGUID();
            me->AddAura(SPELL_PURSUIT, target);
            me->GetThreatMgr().AddThreat(target, PURSUIT_THREAT);
            me->TextEmote("Gri'lek sets his sights on " + target->GetName() + "!", nullptr, true);
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);
            if (spell->Id != SPELL_GROUND_SLAM)
                return;
            for (Player* p : Players(me, [](Player*) { return true; }))
            {
                me->CastSpell(p, SPELL_GROUND_SLAM_HIT, true);
                me->CastSpell(p, SPELL_TRAUMA, true);
            }
            DoCastSelf(SPELL_GROUND_TREMOR, true);
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_PURSUIT:
                        Pursue();
                        events.ScheduleEvent(EVENT_PURSUIT, 20s);
                        break;
                    case EVENT_GROUND_SLAM:
                        DoCastSelf(SPELL_GROUND_SLAM);
                        events.ScheduleEvent(EVENT_GROUND_SLAM, 25s);
                        break;
                    default:
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        ObjectGuid _hunted;
    };
}

void AddCoaGrilekScripts()
{
    RegisterZulGurubCreatureAI(boss_grilek_coa);
}

/*
 * Hakkar the Soulflayer with Ascension's spells.
 *
 * Kit: Ascension's block 2118600-2118705. Hakkar has no cast bars in the video,
 * so the timings come from the Bronzebeard player's DBM (berserk 10 min, first
 * Blood Siphon at 90s, Will of Hakkar at 45s) and from the Heart of Hakkar
 * appearing on screen every 80-90 seconds. Blood Siphon, Blood Scythe and
 * Fierce Blow follow the CoA combat log of 2026-08-02.
 *
 *   Blood Siphon       first 59.5s,           20 seconds of draining everyone:
 *                      every 79.5s            Shadow damage every 2s, a stack of
 *                                             Anemia (-1% healing), Hakkar heals
 *                                             for it. A player with poisoned
 *                                             blood hurts him instead. While he
 *                                             drains, his Heart is exposed:
 *                                             damage to it goes to him, and 10%
 *                                             of his health dealt through it ends
 *                                             the siphon early.
 *   Corrupted Blood    first 25s, every 30s   everyone: stacking Plague damage
 *                                             that heals him; when it ends, a
 *                                             Pool of Corrupted Blood stays
 *   Will of Hakkar     first 45s, every 45s   a player feels it for 5s, then is
 *                                             his for 15s
 *   Blood Scythe       first 10s, every 15s   cone in front, -10% armour, stacks 10
 *   Sons of Hakkar     first 45s, every 60s   two join; where one dies its blood
 *                                             pools and poisons those inside
 *   Aspects            one for each High Priest still alive, +25% damage and
 *                      -10% damage taken each: at the pull he drains the Avatar
 *                      of each living priest's loa (Drain Power, -99% damage
 *                      taken while any of them lives) and gains its Aspect when
 *                      it dies
 *   Fierce Blow        tank, first 6.7-17.3s, then every 6-10s
 *   Berserk            at 10 minutes
 *
 * Decided here, not in the data:
 *   - the siphon's length, the heart's 10% and where the heart appears;
 *   - the DBM bar "Pet Wind Serpent" (every 60s) is read as the wave of Sons of
 *     Hakkar: the siphon mechanic needs poisoned blood, and the data says it
 *     comes from a Son of Hakkar. Two per wave;
 *   - the Aspects are Ascension's buffs instead of the stock aspect spells;
 *   - the avatars stand in a ring 10 yards around him (nothing in the data says
 *     where; his Drain Power has no range limit);
 *   - Animate Blood and Rain of Blood are left out (the
 *     Orb of Corrupted Blood exists nowhere in the data).
 * The Heart is creature 92005, as in the log: the stock one (15069) despawns itself.
 */

