using namespace coa_zg;

namespace
{
    enum Says
    {
        SAY_AGGRO         = 0,
        SAY_CALL_RIDERS   = 1,
        SAY_DEATH         = 2,
        EMOTE_SUMMON_BATS = 3,
        EMOTE_GREAT_HEAL  = 4
    };

    enum Spells
    {
        SPELL_GREEN_CHANNELING    = 13540,
        SPELL_BAT_FORM            = 23966,

        INFO_MIND_FLAY            = 2106101,
        SPELL_MIND_FLAY           = 2106105,
        INFO_SHADOW_WORD_PAIN     = 2106108,
        SPELL_SHADOW_WORD_PAIN    = 2106112,
        SPELL_SHADOW_WORD_PAIN_DOT = 2106113,
        SPELL_MASS_FEAR           = 2106114,
        SPELL_MASS_FEAR_HIT       = 2106115,
        SPELL_GREATER_HEAL        = 2106116,
        SPELL_CURSE_OF_BLOOD      = 2106117,
        SPELL_CURSE_OF_BLOOD_HIT  = 2106118,
        SPELL_CALL_OF_HIREEK      = 2106120,
        SPELL_DRAIN_POWER         = 2106121,
        SPELL_ASPECT_OF_HIREEK    = 2106122,
        SPELL_GIFT_OF_THE_BLOOD_GOD = 2106123,
        SPELL_BATTERING_CHARGE    = 2106125,
        SPELL_BATTERING_STUN      = 2106126,
        SPELL_BATTERING_IMPACT    = 2106127,
        SPELL_SCREECH             = 2106131,
        INFO_SCREECH              = 2106132,
        SPELL_SCREECH_HIT         = 2106136,
        SPELL_VAMPIRISM           = 2106138,
    };

    enum Npcs
    {
        NPC_BLOODSEEKER_BAT = 11368,
        NPC_BATRIDER        = 14750,
        NPC_AVATAR_OF_HIREEK = 666992
    };

    enum Events
    {
        EVENT_MIND_FLAY = 1,
        EVENT_MASS_FEAR,
        EVENT_SHADOW_WORD_PAIN,
        EVENT_CURSE_OF_BLOOD,
        EVENT_CALL_OF_HIREEK,
        EVENT_GREATER_HEAL,
        EVENT_BATTERING_CHARGE,
        EVENT_SCREECH,
        EVENT_BAT_RIDER,
        EVENT_FIERCE_BLOW,
    };

    enum Phases
    {
        PHASE_TROLL = 1,
        PHASE_BAT   = 2
    };

    constexpr uint32 PATH_JEKLIK_INTRO = 145170;
    constexpr float MASS_FEAR_RANGE    = 20.0f;
    constexpr float SCREECH_RANGE      = 100.0f;

    Position const SpawnBat[6] =
    {
        { -12291.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12289.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12293.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12291.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12289.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12293.6220f, -1380.2640f, 144.8304f, 5.483f }
    };
    Position const SpawnBatRider = { -12301.689f, -1371.2921f, 145.09244f, 0.0f };
    Position const JeklikCaveHomePosition = { -12291.9f, -1380.08f, 144.902f, 2.28638f };

    struct boss_jeklik_coa : public BossAI
    {
        boss_jeklik_coa(Creature* creature) : BossAI(creature, DATA_JEKLIK) { }

        void Reset() override
        {
            BossAI::Reset();
            me->SetHomePosition(JeklikCaveHomePosition);
            me->SetDisableGravity(false);
            me->SetReactState(REACT_PASSIVE);
            me->SetCombatMovement(false);
            me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_HIREEK);
            me->RemoveAurasDueToSpell(SPELL_VAMPIRISM);
            me->RemoveAurasDueToSpell(SPELL_GIFT_OF_THE_BLOOD_GOD);
            _avatar.Despawn(me);
            _bat = false;
            _riders = 0;
            DoCastSelf(SPELL_GREEN_CHANNELING, true);
        }

        // From stock: she flies down from her cave in bat form.
        void JustEngagedWith(Unit* who) override
        {
            BossAI::JustEngagedWith(who);
            Talk(SAY_AGGRO);
            DoZoneInCombat();
            me->RemoveAurasDueToSpell(SPELL_GREEN_CHANNELING);
            me->SetDisableGravity(true);
            DoCastSelf(SPELL_BAT_FORM, true);
            me->GetMotionMaster()->MoveWaypoint(PATH_JEKLIK_INTRO, false);
        }

        void PathEndReached(uint32 pathId) override
        {
            BossAI::PathEndReached(pathId);
            me->RemoveAurasDueToSpell(SPELL_BAT_FORM);
            me->SetDisableGravity(false);
            me->SetCombatMovement(true);
            me->SetReactState(REACT_AGGRESSIVE);
            _avatar.Summon(me);

            events.SetPhase(PHASE_TROLL);
            events.ScheduleEvent(EVENT_MIND_FLAY, 4s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_MASS_FEAR, 12s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, 15s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_CURSE_OF_BLOOD, 16s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_CALL_OF_HIREEK, 22s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_GREATER_HEAL, 21s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_FIERCE_BLOW, FIERCE_BLOW_FIRST_MIN, FIERCE_BLOW_FIRST_MAX);
        }

        void EnterEvadeMode(EvadeReason why) override
        {
            if (why != EvadeReason::EVADE_REASON_NO_PATH)
                me->DespawnOnEvade(5s);
            _avatar.Despawn(me);
            BossAI::EnterEvadeMode(why);
        }

        void JustDied(Unit* killer) override
        {
            BossAI::JustDied(killer);
            _avatar.Despawn(me);
            Talk(SAY_DEATH);
        }

        void DamageTaken(Unit* attacker, uint32& damage, DamageEffectType type, SpellSchoolMask school) override
        {
            BossAI::DamageTaken(attacker, damage, type, school);

            if (_bat || !me->HealthBelowPctDamaged(50, damage))
                return;

            _bat = true;
            if (!_avatar.Drain(me))
                TakeBatForm();
        }

        void TakeBatForm()
        {
            me->InterruptNonMeleeSpells(false);
            DoCastSelf(SPELL_GIFT_OF_THE_BLOOD_GOD, true);
            DoCastSelf(SPELL_ASPECT_OF_HIREEK, true);
            DoCastSelf(SPELL_VAMPIRISM, true);
            DoResetThreatList();

            events.SetPhase(PHASE_BAT);
            events.ScheduleEvent(EVENT_BATTERING_CHARGE, 2s, 0, PHASE_BAT);
            events.ScheduleEvent(EVENT_SCREECH, 4s, 0, PHASE_BAT);
            events.ScheduleEvent(EVENT_BAT_RIDER, 10s, 0, PHASE_BAT);
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            Unit* target = ObjectAccessor::GetUnit(*me, _target);
            switch (spell->Id)
            {
                case SPELL_MASS_FEAR:
                    for (Player* p : PlayersWithin(me, MASS_FEAR_RANGE))
                        me->CastSpell(p, SPELL_MASS_FEAR_HIT, true);
                    break;
                case SPELL_SHADOW_WORD_PAIN:
                    Hit(me, target, SPELL_SHADOW_WORD_PAIN_DOT, Info(me, INFO_SHADOW_WORD_PAIN));
                    break;
                case SPELL_CURSE_OF_BLOOD:
                    if (target)
                        me->CastSpell(target, SPELL_CURSE_OF_BLOOD_HIT, true);
                    break;
                case SPELL_CALL_OF_HIREEK:
                    CallOfHireek();
                    break;
                case SPELL_SCREECH:
                {
                    int32 const full = Info(me, INFO_SCREECH);
                    for (Player* p : PlayersWithin(me, SCREECH_RANGE))
                        Hit(me, p, SPELL_SCREECH_HIT, int32(full * (1.0f - me->GetDistance(p) / SCREECH_RANGE)), 1);
                    break;
                }
                default:
                    break;
            }
        }

        // The charge stuns its target; the impact around it is its own spell.
        void SpellHitTarget(Unit* target, SpellInfo const* spell) override
        {
            if (spell->Id == SPELL_BATTERING_STUN)
                me->CastSpell(target, SPELL_BATTERING_IMPACT, true);
        }

        void CallOfHireek()
        {
            Talk(EMOTE_SUMMON_BATS);
            Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 100.0f, true);
            for (Position const& pos : SpawnBat)
                if (Creature* bat = me->SummonCreature(NPC_BLOODSEEKER_BAT, pos, TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT, 15000))
                    if (target)
                        bat->AI()->AttackStart(target);
        }

        bool CastOnRandom(uint32 spell, bool notTank = false)
        {
            if (Unit* target = SelectTarget(SelectTargetMethod::Random, notTank ? 1 : 0, 100.0f, true))
            {
                _target = target->GetGUID();
                DoCast(target, spell);
                return true;
            }
            return false;
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            if (_avatar.Consumed(me))
                TakeBatForm();

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_MIND_FLAY:
                        if (Unit* tank = me->GetVictim())
                        {
                            int32 tick = Info(me, INFO_MIND_FLAY);
                            me->CastCustomSpell(tank, SPELL_MIND_FLAY, nullptr, &tick, nullptr, false);
                        }
                        events.ScheduleEvent(EVENT_MIND_FLAY, 14s, 0, PHASE_TROLL);
                        break;
                    case EVENT_MASS_FEAR:
                        DoCastSelf(SPELL_MASS_FEAR);
                        events.ScheduleEvent(EVENT_MASS_FEAR, 44s, 0, PHASE_TROLL);
                        break;
                    case EVENT_SHADOW_WORD_PAIN:
                        CastOnRandom(SPELL_SHADOW_WORD_PAIN);
                        events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, 27s, 0, PHASE_TROLL);
                        break;
                    case EVENT_CURSE_OF_BLOOD:
                        CastOnRandom(SPELL_CURSE_OF_BLOOD);
                        events.ScheduleEvent(EVENT_CURSE_OF_BLOOD, 31s, 0, PHASE_TROLL);
                        break;
                    case EVENT_CALL_OF_HIREEK:
                        DoCastSelf(SPELL_CALL_OF_HIREEK);
                        events.ScheduleEvent(EVENT_CALL_OF_HIREEK, 60s, 0, PHASE_TROLL);
                        break;
                    case EVENT_GREATER_HEAL:
                        Talk(EMOTE_GREAT_HEAL);
                        DoCastSelf(SPELL_GREATER_HEAL);
                        events.ScheduleEvent(EVENT_GREATER_HEAL, 46s, 0, PHASE_TROLL);
                        break;
                    case EVENT_BATTERING_CHARGE:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, [this](Unit* u) { return u->IsPlayer() && !me->IsWithinMeleeRange(u); }))
                            DoCast(target, SPELL_BATTERING_CHARGE);
                        events.ScheduleEvent(EVENT_BATTERING_CHARGE, 20s, 0, PHASE_BAT);
                        break;
                    case EVENT_SCREECH:
                        DoCastSelf(SPELL_SCREECH);
                        events.ScheduleEvent(EVENT_SCREECH, 20s, 0, PHASE_BAT);
                        break;
                    case EVENT_BAT_RIDER:
                        if (_riders < 2)
                        {
                            Talk(SAY_CALL_RIDERS);
                            if (me->SummonCreature(NPC_BATRIDER, SpawnBatRider, TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT))
                                ++_riders;
                            if (_riders < 2)
                                events.ScheduleEvent(EVENT_BAT_RIDER, 10s, 15s, 0, PHASE_BAT);
                        }
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        bool _bat = false;
        uint8 _riders = 0;
        LoaAvatar _avatar{ NPC_AVATAR_OF_HIREEK, SPELL_DRAIN_POWER };
        ObjectGuid _target;
    };
}

void AddCoaJeklikScripts()
{
    RegisterZulGurubCreatureAI(boss_jeklik_coa);
}

/*
 * Jin'do the Hexxer with Ascension's spells.
 *
 * Kit: Ascension's block 2118500-2118562. Timings: a Bronzebeard kill on video,
 * see raid-difficulty-werkzeug/zg-video-zeitplan.json.
 *
 *   Delusions of Jin'do   first 14s, every 20s    random player: sees the
 *                                                 Other Side, a Shade of Jin'do
 *                                                 hunts them, Shadow damage every
 *                                                 5s that doubles every 10s,
 *                                                 +350% damage against undead
 *   Brain Wash Totem      first 17s, every 60s    the totem casts Brainwash on
 *                                                 a player: stunned and
 *                                                 pacified while it stands
 *   Animate Bones         first 23s, every 30s    the Sacrificed Trolls in the
 *                                                 Blood Pit rise again
 *   Healing Stream Totem  first 202s, every 120s  casts Healing Stream on him:
 *                                                 every second 1% of his missing
 *                                                 health while it stands
 *   Friends On the Other Side  +2% damage for every shade alive
 *
 * From stock: the shade, the totems, the teleport into the pit (Banish) and
 * Hex, and the dance when the raid wipes.
 *
 * Decided here, not in the data:
 *   - the totems are the stock creatures, summoned by Ascension's cast bars;
 *     that the brain wash totem casts Brainwash and the ward casts Healing
 *     Stream is read from the spells' names and targets. Both auras last
 *     seven days in the data, so they end when their totem dies or despawns;
 *   - Hex and the teleport stay: instant casts do not show in the video, and
 *     Animate Bones only makes sense with players sent into the pit;
 *   - Seeking Shadow Bolts (in the block, never seen) is left out.
 */

#include "CreatureScript.h"
#include "GameTime.h"
#include "ScriptedCreature.h"
#include "SpellAuraEffects.h"
#include "SpellScript.h"
#include "SpellScriptLoader.h"
#include "TemporarySummon.h"
#include "../../../src/server/scripts/EasternKingdoms/ZulGurub/zulgurub.h"
#include "zg_coa_common.h"

#include <list>
#include <map>

using namespace coa_zg;

namespace
{
    enum Say
    {
        SAY_AGGRO = 1
    };

    enum Spells
    {
        SPELL_BRAIN_WASH_TOTEM         = 24262,
        SPELL_POWERFULL_HEALING_WARD   = 24309,
        SPELL_HEX                      = 17172,
        SPELL_SUMMON_SHADE_OF_JINDO    = 24308,
        SPELL_BANISH                   = 24466,

        SPELL_SUMMON_BRAIN_WASH        = 2118501,
        SPELL_BRAINWASH                = 2118502,
        SPELL_SUMMON_HEALING_STREAM    = 2118503,
        SPELL_HEALING_STREAM           = 2118504,
        SPELL_HEALING_STREAM_HEAL      = 2118506,
        SPELL_DELUSIONS                = 2118510,
        SPELL_DELUSIONS_VISION         = 2118511,
        SPELL_DELUSIONS_DOT            = 2118512,
        SPELL_FRIENDS_ON_THE_OTHER_SIDE = 2118518,
        SPELL_ANIMATE_BONES            = 2118560,
    };

    enum Events
    {
        EVENT_DELUSIONS = 1,
        EVENT_BRAIN_WASH,
        EVENT_ANIMATE_BONES,
        EVENT_HEALING_STREAM,
        EVENT_HEX,
        EVENT_TELEPORT,
        EVENT_DELUSIONS_GROW,
    };

    enum Npcs
    {
        NPC_POWERFUL_HEALING_WARD = 14987
    };

    constexpr Milliseconds DELUSIONS_DOUBLING = 10s;

    struct boss_jindo_coa : public BossAI
    {
        boss_jindo_coa(Creature* creature) : BossAI(creature, DATA_JINDO) { }

        void Reset() override
        {
            BossAI::Reset();
            _delusions.clear();
            _shades = 0;
            me->RemoveAurasDueToSpell(SPELL_FRIENDS_ON_THE_OTHER_SIDE);
            ReleaseTotemAuras(true);
        }

        void JustEngagedWith(Unit* who) override
        {
            BossAI::JustEngagedWith(who);
            Talk(SAY_AGGRO);
            me->SetUInt32Value(UNIT_NPC_EMOTESTATE, EMOTE_STATE_NONE);

            events.ScheduleEvent(EVENT_TELEPORT, 5s);
            events.ScheduleEvent(EVENT_HEX, 8s);
            events.ScheduleEvent(EVENT_DELUSIONS, 14s);
            events.ScheduleEvent(EVENT_BRAIN_WASH, 17s);
            events.ScheduleEvent(EVENT_ANIMATE_BONES, 23s);
            events.ScheduleEvent(EVENT_HEALING_STREAM, 202s);
            events.ScheduleEvent(EVENT_DELUSIONS_GROW, 1s);
        }

        void JustSummoned(Creature* summon) override
        {
            BossAI::JustSummoned(summon);
            if (summon->GetEntry() == NPC_BRAIN_WASH_TOTEM)
            {
                summon->SetReactState(REACT_PASSIVE);
                if (Unit* target = SelectTarget(SelectTargetMethod::Random, me->GetThreatMgr().GetThreatListSize() > 1 ? 1 : 0))
                    summon->CastSpell(target, SPELL_BRAINWASH, false);
            }
            else if (summon->GetEntry() == NPC_POWERFUL_HEALING_WARD)
                summon->CastSpell(me, SPELL_HEALING_STREAM, false);
        }

        // Totems do not report their despawn, so the auras are checked against their caster.
        void ReleaseTotemAuras(bool all)
        {
            auto orphaned = [all](Aura const* aura)
            {
                Unit* totem = aura->GetCaster();
                return all || !totem || !totem->IsAlive();
            };
            me->GetMap()->DoForAllPlayers([&](Player* player)
            {
                if (Aura* aura = player->GetAura(SPELL_BRAINWASH))
                    if (orphaned(aura))
                        player->RemoveAura(aura);
            });
            if (Aura* aura = me->GetAura(SPELL_HEALING_STREAM))
                if (orphaned(aura))
                    me->RemoveAura(aura);
        }

        void JustDied(Unit* killer) override
        {
            BossAI::JustDied(killer);
            ReleaseTotemAuras(true);
        }

        // +2% damage per shade alive.
        void UpdateFriends()
        {
            // The shades are summoned by the cursed players, not by him.
            std::list<Creature*> found;
            me->GetCreatureListWithEntryInGrid(found, NPC_SHADE_OF_JINDO, 200.0f);
            uint8 shades = 0;
            for (Creature* c : found)
                if (c->IsAlive())
                    ++shades;
            if (shades == _shades)
                return;
            _shades = shades;

            me->RemoveAurasDueToSpell(SPELL_FRIENDS_ON_THE_OTHER_SIDE);
            if (!shades)
                return;
            // CastCustomSpell adds the spell's one point of dice on top.
            int32 bonus = Info(me, SPELL_FRIENDS_ON_THE_OTHER_SIDE, 1) * shades - 1;
            me->CastCustomSpell(me, SPELL_FRIENDS_ON_THE_OTHER_SIDE, nullptr, &bonus, nullptr, true);
        }

        void TrackShades(Unit* summoner)
        {
            std::list<Creature*> shades;
            summoner->GetCreatureListWithEntryInGrid(shades, NPC_SHADE_OF_JINDO, 5.0f);
            for (Creature* shade : shades)
                if (shade->IsSummon() && shade->ToTempSummon()->GetSummonerGUID() == summoner->GetGUID())
                    _shadeGuids.insert(shade->GetGUID());
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            switch (spell->Id)
            {
                case SPELL_DELUSIONS:
                    if (Unit* target = ObjectAccessor::GetUnit(*me, _target))
                    {
                        me->AddAura(SPELL_DELUSIONS_VISION, target);
                        me->CastSpell(target, SPELL_DELUSIONS_DOT, true);
                        target->CastSpell(target, SPELL_SUMMON_SHADE_OF_JINDO, true);
                        TrackShades(target);
                        _delusions[target->GetGUID()] = GameTime::GetGameTimeMS();
                    }
                    break;
                case SPELL_SUMMON_BRAIN_WASH:
                    DoCastSelf(SPELL_BRAIN_WASH_TOTEM, true);
                    break;
                case SPELL_SUMMON_HEALING_STREAM:
                    DoCastSelf(SPELL_POWERFULL_HEALING_WARD, true);
                    break;
                case SPELL_ANIMATE_BONES:
                {
                    std::list<Creature*> trolls;
                    me->GetCreatureListWithEntryInGrid(trolls, NPC_SACRIFICED_TROLL, 150.0f);
                    for (Creature* troll : trolls)
                        if (!troll->IsAlive())
                            troll->Respawn(true);
                    break;
                }
                default:
                    break;
            }
        }

        // The Delusions damage doubles every 10 seconds on each target.
        void GrowDelusions()
        {
            uint32 const now = GameTime::GetGameTimeMS().count();
            for (auto it = _delusions.begin(); it != _delusions.end();)
            {
                Unit* target = ObjectAccessor::GetUnit(*me, it->first);
                AuraEffect* dot = target ? target->GetAuraEffect(sSpellMgr->GetSpellIdForDifficulty(SPELL_DELUSIONS_DOT, me), EFFECT_0) : nullptr;
                if (!dot)
                {
                    it = _delusions.erase(it);
                    continue;
                }
                uint32 const steps = (now - uint32(it->second.count())) / uint32(DELUSIONS_DOUBLING.count());
                int32 const base = Info(me, SPELL_DELUSIONS_DOT);
                int32 const wanted = base << std::min<uint32>(steps, 5);
                if (dot->GetAmount() != wanted)
                    dot->ChangeAmount(wanted);
                ++it;
            }
        }

        void DespawnShades()
        {
            for (ObjectGuid const& guid : _shadeGuids)
                if (Creature* shade = ObjectAccessor::GetCreature(*me, guid))
                    shade->DespawnOrUnsummon();
            _shadeGuids.clear();
        }

        void EnterEvadeMode(EvadeReason why) override
        {
            if (CreatureAI::_EnterEvadeMode(why))
            {
                DespawnShades();
                Reset();
                me->SetUInt32Value(UNIT_NPC_EMOTESTATE, EMOTE_STATE_DANCE);
                Creature* jindo = me;
                me->m_Events.AddEventAtOffset([jindo]()
                {
                    jindo->SetUInt32Value(UNIT_NPC_EMOTESTATE, EMOTE_STATE_NONE);
                    jindo->GetMotionMaster()->MoveTargetedHome();
                }, 4s);
            }
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_DELUSIONS:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 100.0f, true, true, -int32(SPELL_DELUSIONS_VISION)))
                        {
                            _target = target->GetGUID();
                            DoCast(target, SPELL_DELUSIONS);
                        }
                        events.ScheduleEvent(EVENT_DELUSIONS, 20s);
                        break;
                    case EVENT_BRAIN_WASH:
                        DoCastSelf(SPELL_SUMMON_BRAIN_WASH);
                        events.ScheduleEvent(EVENT_BRAIN_WASH, 60s);
                        break;
                    case EVENT_ANIMATE_BONES:
                        DoCastSelf(SPELL_ANIMATE_BONES);
                        events.ScheduleEvent(EVENT_ANIMATE_BONES, 30s);
                        break;
                    case EVENT_HEALING_STREAM:
                        DoCastSelf(SPELL_SUMMON_HEALING_STREAM);
                        events.ScheduleEvent(EVENT_HEALING_STREAM, 120s);
                        break;
                    case EVENT_HEX:
                        if (me->GetThreatMgr().GetThreatListSize() > 1)
                            DoCastVictim(SPELL_HEX, true);
                        events.ScheduleEvent(EVENT_HEX, 12s, 20s);
                        break;
                    case EVENT_TELEPORT:
                        DoCastRandomTarget(SPELL_BANISH);
                        events.ScheduleEvent(EVENT_TELEPORT, 15s, 23s);
                        break;
                    case EVENT_DELUSIONS_GROW:
                        GrowDelusions();
                        UpdateFriends();
                        ReleaseTotemAuras(false);
                        events.ScheduleEvent(EVENT_DELUSIONS_GROW, 1s);
                        break;
                    default:
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        ObjectGuid _target;
        std::map<ObjectGuid, Milliseconds> _delusions;
        uint8 _shades = 0;
        GuidSet _shadeGuids;
    };

    // Healing Stream: every second its first value in percent of the target's missing health.
    class spell_jindo_coa_healing_stream : public AuraScript
    {
        PrepareAuraScript(spell_jindo_coa_healing_stream);

        bool Validate(SpellInfo const* /*spellInfo*/) override
        {
            return ValidateSpellInfo({ SPELL_HEALING_STREAM_HEAL });
        }

        void HandlePeriodic(AuraEffect const* /*aurEff*/)
        {
            PreventDefaultAction();
            Unit* caster = GetCaster();
            Unit* target = GetTarget();
            if (!caster || target->IsFullHealth())
                return;
            int32 heal = int32(CalculatePct(target->GetMaxHealth() - target->GetHealth(),
                GetSpellInfo()->Effects[EFFECT_0].CalcValue(caster)));
            if (heal > 0)
                caster->CastCustomSpell(target, SPELL_HEALING_STREAM_HEAL, &heal, nullptr, nullptr, true);
        }

        void Register() override
        {
            OnEffectPeriodic += AuraEffectPeriodicFn(spell_jindo_coa_healing_stream::HandlePeriodic, EFFECT_1,
                SPELL_AURA_PERIODIC_TRIGGER_SPELL);
        }
    };
}

