    RegisterZulGurubCreatureAI(boss_thekal_coa);
    RegisterSpellScript(spell_thekal_coa_zath_strike);
    RegisterSpellScript(spell_thekal_coa_storm_shield);
    RegisterSpellScript(spell_thekal_coa_storm_shield_charge);
